<?php
namespace Wortek\Store\Controllers;
use Wortek\Store\Http\Response; use Wortek\Store\Repositories\UserRepository;
final class UserController { public function __construct(private UserRepository $r){} public function index(): never{Response::success(['utilizadores'=>$this->r->all(),'perfis'=>$this->r->profiles()]);} public function store(): never{$d=json_decode(file_get_contents('php://input'),true);if(!is_array($d)||empty($d['nome'])||empty($d['email'])||empty($d['senha'])||empty($d['perfil_id']))Response::error('Dados obrigatórios em falta.',422);if(!filter_var($d['email'],FILTER_VALIDATE_EMAIL)||strlen((string)$d['senha'])<8)Response::error('Email ou senha inválidos.',422);$id=$this->r->create(['nome'=>trim($d['nome']),'email'=>strtolower(trim($d['email'])),'telefone'=>trim((string)($d['telefone']??''))?:null,'senha'=>password_hash($d['senha'],PASSWORD_DEFAULT),'perfil_id'=>(int)$d['perfil_id'],'estado'=>$d['estado']??'ativo']);Response::success(['message'=>'Utilizador criado.','id'=>$id],201);} public function update(int $id): never{$d=json_decode(file_get_contents('php://input'),true);if(!is_array($d)||empty($d['nome'])||empty($d['email'])||empty($d['perfil_id']))Response::error('Dados inválidos.',422);$this->r->update($id,['nome'=>trim($d['nome']),'email'=>strtolower(trim($d['email'])),'telefone'=>trim((string)($d['telefone']??''))?:null,'perfil_id'=>(int)$d['perfil_id'],'estado'=>$d['estado']??'ativo']);Response::success(['message'=>'Utilizador actualizado.']);} }
